const QUIET_MS = 25_000

function watchdog(stream: EventStream, reconnect: () => void) {
  let timer = setTimeout(fire, QUIET_MS)
  function fire() {
    stream.close()
    reconnect()
  }
  stream.on("message", () => {
    clearTimeout(timer)
    timer = setTimeout(fire, QUIET_MS)
  })
}

import { expect, test } from "bun:test"
import { Backoff } from "./backoff"

test("flapping keeps backing off", () => {
  const clock = fakeClock()
  const b = new Backoff({ clock, base: 1000, cap: 30_000 })
  const delays = [1, 2, 3, 4].map(() => {
    b.message()
    return b.fail()
  })
  expect(delays).toEqual([1000, 2000, 4000, 8000])
})
